	else:
		ending_id = "END-TWILIGHT-06"
		ending_enum = EndingType.SILENT_TWILIGHT

	return {
		"ending_id": ending_id,
		"ending_enum": ending_enum,
		"destiny_rating": score,
		"timestamp": Time.get_datetime_string_from_system()
	}
